function [obj,params] = loadSessionData(meta,params, varargin)

% varargin only accepts one input right now -> params.behav_only. If 1,
% don't process clusters
if nargin > 2
    behav_only = varargin{1};
else
    behav_only = 0;
end

disp("LOADING ALL DATA OBJECTS")
obj = loadObjs(meta);


for sessix = 1:numel(meta)
    for prbix = 1:numel(params.probe{sessix})
        disp('______________________________________________________')
        disp(['Processing data for session ' [meta(sessix).anm '_' meta(sessix).date ' | Probe' num2str(params.probe{sessix}(prbix))   ]])
        disp(' ')

        prbnum = params.probe{sessix}(prbix);

        [sessparams{sessix,prbix},sessobj{sessix,prbix}] = processData(obj(sessix),params,prbnum, behav_only);
    end
end

% clean up sessparams and sessobj
for sessix = 1:numel(meta)
    params.trialid{sessix} = sessparams{sessix}.trialid;

    if numel(params.probe{sessix}) == 1
        params.cluid{sessix} = sessparams{sessix,1}.cluid{params.probe{sessix}};
        params.cluid_all{sessix} = params.cluid{sessix};
        params.probeid{sessix} = sessparams{sessix,1}.probeid{params.probe{sessix}};
        params.probeid_all{sessix} = params.probeid{sessix};

        objs(sessix) = sessobj{sessix,1};

        if behav_only
            continue;
        end

        objs(sessix).psth = objs(sessix).psth{params.probe{sessix}};
        objs(sessix).trialdat = objs(sessix).trialdat{params.probe{sessix}};
        objs(sessix).presampleFR = objs(sessix).presampleFR{params.probe{sessix}};
        objs(sessix).presampleSigma = objs(sessix).presampleSigma{params.probe{sessix}};
    elseif numel(params.probe{sessix}) == 2 % concatenate both probes worth of data

        params.cluid{sessix} = {sessparams{sessix,1}.cluid{params.probe{sessix}(1)}, sessparams{sessix,2}.cluid{params.probe{sessix}(2)} };
        params.cluid_all{sessix} = cell2mat(params.cluid{sessix}');
        params.probeid{sessix} = {sessparams{sessix,1}.probeid{params.probe{sessix}(1)}, sessparams{sessix,2}.probeid{params.probe{sessix}(2)} };
        params.probeid_all{sessix} = cell2mat(params.probeid{sessix}');

        objs(sessix) = sessobj{sessix,1};

        if behav_only
            continue;
        end

        objs(sessix).psth = cat(2, objs(sessix).psth{1}, sessobj{sessix,2}.psth{2});
        objs(sessix).trialdat = cat(2, objs(sessix).trialdat{1}, sessobj{sessix,2}.trialdat{2});
        objs(sessix).presampleFR = cat(1, objs(sessix).presampleFR{1}, sessobj{sessix,2}.presampleFR{2});
        objs(sessix).presampleSigma = cat(1, objs(sessix).presampleSigma{1}, sessobj{sessix,2}.presampleSigma{2});

        % assign trialtm_aligned for 2nd probe
        for i = 1:numel(objs(sessix).clu{2})
            objs(sessix).clu{2}(i).trialtm_aligned = sessobj{sessix,2}.clu{2}(i).trialtm_aligned;
        end
    end
end

disp(' ')
disp('DATA LOADED AND PROCESSED')
disp(' ')


clear obj
obj = objs;
clear objs


%% convert params to a struct array (just for convenience)

temp = params;
clear params
for sessix = 1:numel(meta)
    temp2 = rmfield(temp,{'probe','trialid','cluid','cluid_all','probeid','probeid_all'});
    temp2.probe = temp.probe{sessix};
    temp2.trialid = temp.trialid{sessix};
    temp2.cluid = temp.cluid{sessix};
    temp2.cluid_all = temp.cluid_all{sessix};
    temp2.probeid = temp.probeid{sessix};
    temp2.probeid_all = temp.probeid_all{sessix};
    params(sessix) = temp2;
end
function params = getDefaultParams()

params.alignEvent          = 'goCue'; % 'jawOnset' 'goCue'  'moveOnset'  'firstLick'  'lastLick'

% time warping only operates on neural data for now.
% TODO: time warp for video and bpod data
params.timeWarp            = 0;  % piecewise linear time warping - each lick duration on each trial gets warped to median lick duration for that lick across trials
params.nLicks              = 20; % number of post go cue licks to calculate median lick duration for and warp individual trials to 

params.lowFR               = 0.5; % remove clusters with firing rates across all trials less than this val

% set conditions to calculate PSTHs for
params.condition(1)     = {'R&hit&~stim.enable&~autowater&~early'};         % right hits, no stim, aw off
params.condition(end+1) = {'L&hit&~stim.enable&~autowater&~early'};         % left hits, no stim, aw off
params.condition(end+1) = {'R&hit&~stim.enable&autowater&~early'};          % right hits, no stim, aw on
params.condition(end+1) = {'L&hit&~stim.enable&autowater&~early'};          % left hits, no stim, aw on
% params.condition(end+1) = {'R&miss&~stim.enable&~autowater&~early'};        % error right, no stim, aw off
% params.condition(end+1) = {'L&miss&~stim.enable&~autowater&~early'};        % error left, no stim, aw off
% params.condition(end+1) = {'~hit&~miss&~stim.enable&~autowater&~early'};    % ignore
% params.condition(end+1) = {'hit&~stim.enable&~autowater&~early'};           % hit 2afc
% params.condition(end+1) = {'hit&~stim.enable&autowater&~early'};            % hit aw

% specify probe number and areas to load and process data
params.probe(1) = 1;
params.probeArea{1} = 'ALM';
% 
% params.probe(end+1) = 2;
% params.probeArea{end} = 'ALM';

params.tmin = -2.5;
params.tmax = 2.5;
params.dt = 1/200;

% smooth with causal gaussian kernel
params.smooth = 15;

% cluster qualities to use
params.quality = {'all'}; % accepts any cell array of strings - special character 'all' returns clusters of any quality

% video features to use
% cell array for {cam0_features,cam1_features}
% params.traj_features = {{'tongue','left_tongue','right_tongue','jaw','trident','nose'},...
%                         {'top_tongue','topleft_tongue','bottom_tongue','bottomleft_tongue','top_paw','bottom_paw','jaw'}};

params.traj_features = {{'tongue','left_tongue','right_tongue','jaw','trident','nose'},...
                        {'top_tongue','topleft_tongue','bottom_tongue','bottomleft_tongue','jaw','top_paw','bottom_paw','top_nostril','bottom_nostril'}};

params.feat_varToExplain = 80; % num factors for dim reduction of video features should explain this much variance


% --SPECIFY TIME POINTS AND LAG TO USE
params.prep = [-2.5 -0.05]; % initial and final time points (seconds) defining prep epoch, relative to alignevent
params.move = [-2.5 1.5];   % initial and final time points (seconds) defining move epoch, relative to alignevent
% params.advance_movement = 0.025; % seconds, amount of time to advance movement data relative to neural data
params.advance_movement = 0.0;

end


function obj = alignSpikes(obj,params,prbnum)

if strcmp(params.alignEvent,'moveOnset')
    obj.bp.ev.(params.alignEvent) = findMoveOnset(obj);
end

if strcmp(params.alignEvent,'firstLick')
    % get first lick time for left and right licks
    temp = obj.bp.ev.lickL;
    idx = ~cellfun('isempty',temp);
    outL = zeros(size(temp));
    outL(idx) = cellfun(@(v)v(1),temp(idx));
    temp = obj.bp.ev.lickR;
    idx = ~cellfun('isempty',temp);
    outR = zeros(size(temp));
    outR(idx) = cellfun(@(v)v(1),temp(idx));
    firstLick = zeros(size(temp));
    % firstLick = min(outL,outR), except when outL||outR == 0
    outL(outL==0) = nan;
    outR(outR==0) = nan;
    firstLick = nanmin(outL,outR);
    firstLick(isnan(firstLick)) = 0;
    obj.bp.ev.(params.alignEvent) = firstLick;
end
if strcmp(params.alignEvent,'lastLick')
    % get last lick time for left and right licks
    temp = obj.bp.ev.lickL;
    idx = ~cellfun('isempty',temp);
    outL = zeros(size(temp));
    outL(idx) = cellfun(@(v)v(end),temp(idx));
    temp = obj.bp.ev.lickR;
    idx = ~cellfun('isempty',temp);
    outR = zeros(size(temp));
    outR(idx) = cellfun(@(v)v(end),temp(idx));
    lastLick = zeros(size(temp));
    % lastLick = max(outL,outR), except when outL||outR == 0
    outL(outL==0) = nan;
    outR(outR==0) = nan;
    lastLick = nanmax(outL,outR);
    lastLick(isnan(lastLick)) = 0;
    obj.bp.ev.(params.alignEvent) = lastLick;
end

if strcmp(params.alignEvent,'jawOnset')
    % half rise time to first peak of jaw onset after go cue
    view = 1; % side cam
    [~,jawMask] = patternMatchCellArray(obj.traj{view}(1).featNames,{'jaw'},'all');
    feat = find(jawMask); % jaw

    % filter params
    opts.f_cut = 60; % cutoff freq for butter filt
    opts.f_n   = 2;  % filter order

    % peak finding params
    opts.minpkdist = 0.06; % number of ms around peaks to reject peaks
    opts.minpkprom = 10;   % a threshold for the peak size
    obj.bp.ev.(params.alignEvent) = alignJawOnset(view,feat,obj,opts);
end

% align spikes to params.alignEvent
for clu = 1:numel(obj.clu{prbnum})
    event = obj.bp.ev.(params.alignEvent)(obj.clu{prbnum}(clu).trial);

    obj.clu{prbnum}(clu).trialtm_aligned = obj.clu{prbnum}(clu).trialtm - event;
end

end % alignSpikes
function [obj,cluid] = removeLowFRClusters(obj,cluid,lowFR,prbnum)
% % Remove low-firing rate units, e.g., all those firing less than lowFR
%   spikes per second on average across all trials.
%   
%   The fitted observation noise (diagonal element of R) for a
%   low-firing rate unit will be small, so the neural trajectory may
%   show a deflection each time the neuron spikes.

meanFRs = mean(mean(obj.psth{prbnum},3,'omitnan'),'omitnan');
use = meanFRs > lowFR;

% remove low fr clusters
cluid = cluid(use);
obj.psth{prbnum} = obj.psth{prbnum}(:,use,:);
obj.trialdat{prbnum} = obj.trialdat{prbnum}(:,use,:);

end % removeLowFRClustersfunction trialNums = findTrials(obj, conditions)

% % older data objects have obj.bp.autowater.nums
